////////////////////////////////////////////////////////////////////////////////
//
// Conics Through Five Points. mla, 2025.
//
// Just a demo for the conic() function, which uses cross products and 
// swizzling rather niftily to find the conic through five points.
//
// Red conic is the centrally aligned transform of the white conic.
//
// Use mouse to drag red points. Press 'p' for mouse control over the yellow
// point as well.
//
////////////////////////////////////////////////////////////////////////////////

// Returns the 3x3 matrix for the conic through the five parameter
// points (defined with homogeneous coordinates).
mat3 conic(vec3 p, vec3 q, vec3 r, vec3 s, vec3 t) {
  mat3 a = mat3(cross(q,r),cross(r,p),cross(p,q));
  s *= a; t *= a;
  vec4 m = vec4(cross(s*s.yzx,t*t.yzx),0);
  mat3 x = mat3(m.wxz,m.xwy,m.zyw);
  return a*x*transpose(a);
}

float lwidth = 0.007;
float pwidth = 0.03;

const vec3 pcolor = vec3(1,0,0);
const vec3 ccolor = vec3(1,1,1);

vec3 getcol(int i) {
    return 0.5+0.5*h2rgb(float(i)/6.0);
}

// Just a point
float drawpoint(vec3 pos, vec3 p, float px) {
  pos /= pos.z; p /= p.z; // Normalize
  float dist = distance(pos,p);
  if (isnan(dist)) return 0.0;
  return 1.0-smoothstep(-px,px,dist-pwidth);
}

float drawconic(vec3 pos, mat3 m, float px) {
  float dist = dot(pos,m*pos);   // Distance from the conic
  vec3 grad = m*pos*2.0;         // The gradient uses the same matrix.
  dist /= pos.z*length(grad.xy); // Normalize for Euclidean distance
  if (isinf(dist)) return 0.0;
  return 1.0-smoothstep(-px,px,abs(dist)-lwidth);
}

vec3 cmix(vec3 color0, vec3 color1, float level) {
  return mix(color0,color1,0.95*level);
}

// Turn a vec2 point into a homogeneous vec3 point
vec3 ppoint(vec2 p) {
  return vec3(p,1);
}

// Assume the equation of the conic is Ax²+By²+C+Dxy+Ex+Fy
mat3 align(mat3 c) {
  float A = c[0][0];
  float B = c[1][1];
  float D = 2.0*c[0][1];
#if 0
  float theta = 0.5*atan(D/(A-B));
  mat3 r = mat3(rotate((0.5*PI-theta)));
#else
  // Get rotation directly. Avoid atan and get a more accurate result.
  float X = D/(A-B); // tan(2t)
  float k = 0.5*(1.0-sqrt(1.0/(X*X+1.0))); // cos²(t), maximum t for visual effect
  float cost = sqrt(k), sint = -sign(X)*sqrt(1.0-k);
  mat3 r = mat3(mat2(cost,sint,-sint, cost)); // rotate(-t)
#endif  
  return transpose(r)*c*r;
}

mat3 centre(mat3 c) {
  float A = c[0][0], B = c[1][1];
  float E = c[0][2], F = c[1][2];
  mat3 s = mat3(1,0,0, 0,1,0, -E/A,-F/B,1);
  return transpose(s)*c*s;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
  setscale();
  vec3 pos = vec3(map(fragCoord.xy),1);
  float px = fwidth(pos.x);
  vec3 p0 = ppoint(getselection(0)), p1 = ppoint(getselection(1));
  vec3 p2 = ppoint(getselection(2)), p3 = ppoint(getselection(3));
  vec3 p4 = ppoint(getselection(4)), p5 = ppoint(getselection(5));
  if (!key(CHAR_P)) p5 = ppoint(vec2(cos(iTime),1.2*sin(0.618*iTime)));
  mat3 c = conic(p0,p1,p2,p3,p4);
  mat3 d = centre(align(c));
  mat3 c0 = conic(p1,p2,p3,p4,p5);
  mat3 c1 = conic(p0,p2,p3,p4,p5);
  mat3 c2 = conic(p0,p1,p3,p4,p5);
  mat3 c3 = conic(p0,p1,p2,p4,p5);
  mat3 c4 = conic(p0,p1,p2,p3,p5);

  vec3 tex = texture(iChannel1,0.5*fragCoord/iResolution.y).xyz;
  vec3 color = 0.1*tex;
  float t = lwidth*0.5*length(tex);
  lwidth += t;
  pwidth += t;

  color = cmix(color,getcol(0),0.5*drawconic(pos,c0,px));
  color = cmix(color,getcol(1),0.5*drawconic(pos,c1,px));
  color = cmix(color,getcol(2),0.5*drawconic(pos,c2,px));
  color = cmix(color,getcol(3),0.5*drawconic(pos,c3,px));
  color = cmix(color,getcol(4),0.5*drawconic(pos,c4,px));
  color = cmix(color,ccolor,drawconic(pos,c,px));
  color = cmix(color,vec3(1,0,0),0.5*drawconic(pos,d,px));
  color = cmix(color,pcolor,drawpoint(pos,p0,px));
  color = cmix(color,pcolor,drawpoint(pos,p1,px));
  color = cmix(color,pcolor,drawpoint(pos,p2,px));
  color = cmix(color,pcolor,drawpoint(pos,p3,px));
  color = cmix(color,pcolor,drawpoint(pos,p4,px));
  color = cmix(color,vec3(1,1,0),drawpoint(pos,p5,px));
  fragColor = vec4(pow(1.0*color,vec3(0.4545)),1);
}

void mainImage(out vec4 t, vec2 uv) {
  setscale();
  int i = int(uv.x); // Column number
  int j = int(uv.y); // Row
  if (iFrame == 0) {
    t = vec4(0);
  } else {
    t = texelFetch(iChannel2,ivec2(i,j),0); // Get current state   
  }  
  if (j == 0) {
    // First row - key count
    // Do key repeat here as well?
    float w1 = keystate(i,0).x;
    if (w1 != t.w) {
      t.w = w1;
      // Don't count key changes when ALT pressed
      if (keystate(KEY_ALT,0).x == 0.0 && w1 != 0.0) {
        t.x++; t.y = iTime;
      }
    }
    // Key repeat - only when shader is running!
    // Should have longer pause after first key press.
    if (t.w != 0.0 && keystate(KEY_ALT,0).x == 0.0 && iTime-t.y > 0.25) {
      t.x++; t.y = iTime;
    }
  } else if (j == 1) {
    if (i == 0 && iMouse.z != 0.0) t.xy = iMouse.xy;
    if (i == 1 && iMouse.z == 0.0) t.xy = iMouse.xy;
  } else if (j == 2 && key(i)) {
    // Record mouse position when key pressed
    t = vec4(iMouse.xy,0,iTime);
  } else if (j == 3) {
      // Cell 0 holds currently selected item, 0 = no selection
    if (i == 0) {
      if (t.x == 0.0 && iMouse.z > 0.0) {
        vec2 mouse = map(iMouse.xy);
        // No selection, but mouse now down
        for (int i = nselections; i >= 1; i--) {
          // Select topmost item (assume drawn 1..N)
          vec2 p = texelFetch(iChannel2,ivec2(i,3),0).xy; // Get current state
          if (distance(mouse,p) < scale*0.05) {
            t.x = float(i);
            break;
          }
        }
      } else if (t.x != 0.0 && iMouse.z <= 0.0) {
        // Clear selection if mouse up.
        t.x = 0.0;
      }
    } else if (iFrame == 0 || t.w != 1234.0) {
      t.xy = initselection(i-1); // Current coordinates
      t.w = 1234.0;
    } else {
      vec4 t0 = texelFetch(iChannel2,ivec2(0,3),0); // Get current state
      if (int(t0.x) == i && iMouse.z > 0.0) {
        // If currently selected, copy mouse position
        t.xy = map(iMouse.xy);
      }
    }
  }
}

#if !defined(key)
#define key(code) (texelFetch(iChannel3, ivec2((code),2),0).x != 0.0)
#endif
#define store(i,j) (texelFetch(iChannel2, ivec2((i),(j)),0))
#define keycount(code) (int(store((code),0).x))
#define keystate(code,n) ( texelFetch(iChannel3,ivec2(code,n),0) )

#define map(screenpos) (scale*(2.0*(screenpos)-iResolution.xy)/iResolution.y)
#define getselection(i) (texelFetch(iChannel2,ivec2((i)+1,3),0).xy)
#define setscale() (scale *= exp(0.1*float(keycount(KEY_DOWN)-keycount(KEY_UP))))

float scale = 2.0;

#define nselections 6

vec2 initselection(int i) {
  if (i == 0) return vec2(0,-1);
  if (i == 1) return vec2(-1,0.5);
  if (i == 2) return vec2(-0.5,-1);
  if (i == 3) return vec2(1.5,-0.5);
  if (i == 4) return vec2(1.4,0.6);
  if (i == 5) return vec2(0);
  return vec2(0);
}

////////////////////////////////////////////////////////////////////////////////

vec3 h2rgb(float h) {
  vec3 rgb = clamp( abs(mod(h*6.0+vec3(0.0,4.0,2.0),6.0)-3.0)-1.0, 0.0, 1.0 );
  return rgb*rgb*(3.0-2.0*rgb); // cubic smoothing	
}

mat2 rotate(float theta) {
  return mat2(cos(theta),-sin(theta),
              sin(theta),cos(theta));
}

const float PI =  3.141592654;

